/**
 * NOVA_ATELIER_WORLD :: particle-constellation-hero
 * 1) COMPOSITION: backdrop gradient plane (z=-2.5) behind an ellipsoidal shell of
 *    1200 paper-toned instanced icosahedra (field, z ~ -3.5..1.5) wrapping a dense
 *    90-instance accent core at the origin; MSDF hero/subhead/caption planes float
 *    at z=0.5 above/below the core on the 0.25-unit rhythm.
 * 2) LIGHT RIG (rig-underglow-signal): key directional #f8f4ee@2.4 from [1.4,3,2],
 *    red practical point #ff2a38@14 low-under at [0,-0.65,0.6], white rim
 *    directional @1.3 from [-1.4,2,-2.4] — all node-local children of the group.
 * 3) MATERIALS: field = MeshStandardNodeMaterial paper, roughness 1, metalness 0,
 *    self-lit emissive 0.9, per-instance opacity attribute for depth falloff; core =
 *    MeshStandardNodeMaterial accent, additive blending, emissive capped at 1.8.
 * 4) MOTION: ctx.primitives['particle-emerge'] drives the group-level entrance;
 *    a lightweight gsap.ticker drift oscillates each instance +/-0.04u at 0.05Hz,
 *    and a slow sine gsap timeline pulses the core emissive 1.5<->1.8 at 0.1Hz.
 * 5) FOCAL ELEMENT: the accent core — the single brightest, additive-glowing
 *    element in the frame; everything else (field, text) reads dimmer beneath it.
 */

import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, mix, vec3, attribute } from 'three/tsl';
import { gsap } from 'gsap';
import * as PRIMS from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    PlaneGeometry,
    IcosahedronGeometry,
    InstancedMesh,
    InstancedBufferAttribute,
    Color,
    Matrix4,
    Vector3,
    DirectionalLight,
    PointLight,
    Object3D,
    AdditiveBlending,
    NormalBlending,
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#16161d' }],
  };

  const disposables = [];
  const timelines = [];
  const tickerFns = [];

  function hexToVec3(hex) {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  }

  // ---- root group ----------------------------------------------------
  const root = new Group();
  const particleGroup = new Group();
  root.add(particleGroup);

  // ---- BACKDROP: engineered gradient stage (color.gradient) -----------
  const stops = colors.gradientStops ?? [{ at: 0, hex: colors.background }, { at: 1, hex: colors.ink }];
  const gradGeo = new PlaneGeometry(7, 6);
  const gradMat = new MeshBasicNodeMaterial();
  gradMat.colorNode = mix(hexToVec3(stops[0].hex), hexToVec3(stops[stops.length - 1].hex), uv().y);
  gradMat.toneMapped = true;
  const backdrop = new (THREE.Mesh)(gradGeo, gradMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(gradGeo, gradMat);

  // ---- FIELD PARTICLES (color.paper, effects.spec) ---------------------
  const FIELD_COUNT = 1200;
  const CORE_COUNT = 90;
  const shellCenter = new Vector3(0, 0, -1.5);
  const axes = new Vector3(3, 2, 2.5); // half of 6x4x5

  const fieldGeo = new IcosahedronGeometry(0.012, 0);
  const fieldMat = new MeshStandardNodeMaterial();
  fieldMat.color = new Color(colors.paper);
  fieldMat.roughness = 1;
  fieldMat.metalness = 0;
  fieldMat.emissive = new Color(colors.paper);
  fieldMat.emissiveIntensity = 0.9;
  fieldMat.transparent = true;
  fieldMat.depthWrite = false;
  fieldMat.blending = NormalBlending;
  fieldMat.opacityNode = attribute('iOpacity');

  const fieldMesh = new InstancedMesh(fieldGeo, fieldMat, FIELD_COUNT);
  const fieldOpacity = new Float32Array(FIELD_COUNT);
  const fieldAnchors = new Float32Array(FIELD_COUNT * 3);
  const fieldPhases = new Float32Array(FIELD_COUNT);

  const dummy = new Object3D();
  for (let i = 0; i < FIELD_COUNT; i++) {
    // random direction on unit sphere, shell fraction 0.82..1.0
    const u = Math.random() * 2 - 1;
    const theta = Math.random() * Math.PI * 2;
    const r = Math.sqrt(1 - u * u);
    const dirX = r * Math.cos(theta);
    const dirY = r * Math.sin(theta);
    const dirZ = u;
    const shellFrac = 0.82 + Math.random() * 0.18;

    const px = dirX * axes.x * shellFrac + shellCenter.x;
    const py = dirY * axes.y * shellFrac + shellCenter.y;
    const pz = dirZ * axes.z * shellFrac + shellCenter.z;

    fieldAnchors[i * 3] = px;
    fieldAnchors[i * 3 + 1] = py;
    fieldAnchors[i * 3 + 2] = pz;
    fieldPhases[i] = Math.random() * Math.PI * 2;

    const t = Math.min(1, Math.max(0, -pz / 5)); // t=0 at z=0 -> t=1 at z=-5
    fieldOpacity[i] = 0.9 + t * (0.15 - 0.9);

    dummy.position.set(px, py, pz);
    dummy.scale.setScalar(1);
    dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);
  }
  fieldGeo.setAttribute('iOpacity', new InstancedBufferAttribute(fieldOpacity, 1));
  fieldMesh.instanceMatrix.needsUpdate = true;
  particleGroup.add(fieldMesh);
  disposables.push(fieldGeo, fieldMat);

  // ---- ACCENT CORE (color.accent, effects.spec core) -------------------
  const coreGeo = new IcosahedronGeometry(0.012, 0);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color(colors.accent);
  coreMat.roughness = 0.6;
  coreMat.metalness = 0.1;
  coreMat.emissive = new Color(colors.accent);
  coreMat.emissiveIntensity = 1.8; // hard cap, within <=2.3 global ceiling
  coreMat.transparent = true;
  coreMat.depthWrite = false;
  coreMat.blending = AdditiveBlending; // additive ONLY inside the core

  const coreMesh = new InstancedMesh(coreGeo, coreMat, CORE_COUNT);
  const coreAnchors = new Float32Array(CORE_COUNT * 3);
  const corePhases = new Float32Array(CORE_COUNT);
  for (let i = 0; i < CORE_COUNT; i++) {
    const u = Math.random() * 2 - 1;
    const theta = Math.random() * Math.PI * 2;
    const r = Math.sqrt(1 - u * u);
    const radius = Math.random() * 0.5;
    const px = r * Math.cos(theta) * radius;
    const py = r * Math.sin(theta) * radius;
    const pz = u * radius;

    coreAnchors[i * 3] = px;
    coreAnchors[i * 3 + 1] = py;
    coreAnchors[i * 3 + 2] = pz;
    corePhases[i] = Math.random() * Math.PI * 2;

    dummy.position.set(px, py, pz);
    dummy.scale.setScalar(1.4);
    dummy.rotation.set(0, 0, 0);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  particleGroup.add(coreMesh);
  disposables.push(coreGeo, coreMat);

  // ---- AMBIENT DRIFT (effects.spec drift, node-local, one slow transform) ---
  const driftTmp = new Matrix4();
  const driftObj = new Object3D();
  let elapsed = 0;
  function driftTick(time, deltaMs) {
    elapsed += (deltaMs || 16.6) / 1000;
    const freq = 0.05 * Math.PI * 2;
    for (let i = 0; i < FIELD_COUNT; i++) {
      const ph = fieldPhases[i];
      const ox = Math.sin(elapsed * freq + ph) * 0.04;
      const oy = Math.cos(elapsed * freq * 0.8 + ph) * 0.04;
      const oz = Math.sin(elapsed * freq * 0.6 + ph * 1.3) * 0.04;
      driftObj.position.set(
        fieldAnchors[i * 3] + ox,
        fieldAnchors[i * 3 + 1] + oy,
        fieldAnchors[i * 3 + 2] + oz
      );
      driftObj.scale.setScalar(1);
      driftObj.rotation.set(0, 0, 0);
      driftObj.updateMatrix();
      fieldMesh.setMatrixAt(i, driftObj.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < CORE_COUNT; i++) {
      const ph = corePhases[i];
      const ox = Math.sin(elapsed * freq * 1.2 + ph) * 0.02;
      const oy = Math.cos(elapsed * freq + ph) * 0.02;
      const oz = Math.sin(elapsed * freq * 0.9 + ph) * 0.02;
      driftObj.position.set(
        coreAnchors[i * 3] + ox,
        coreAnchors[i * 3 + 1] + oy,
        coreAnchors[i * 3 + 2] + oz
      );
      driftObj.scale.setScalar(1.4);
      driftObj.rotation.set(0, 0, 0);
      driftObj.updateMatrix();
      coreMesh.setMatrixAt(i, driftObj.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;
  }
  gsap.ticker.add(driftTick);
  tickerFns.push(driftTick);

  // ---- CORE PULSE (effects.spec: emissive 1.5->1.8 @0.1Hz) -------------
  const pulseTl = gsap.timeline({ repeat: -1, yoyo: true });
  pulseTl.to(coreMat, { emissiveIntensity: 1.5, duration: 5, ease: 'sine.inOut' });
  timelines.push(pulseTl);

  // ---- LIGHT RIG (rig-underglow-signal, node-local) ---------------------
  const keyLight = new DirectionalLight(new Color('#f8f4ee'), 2.4);
  keyLight.position.set(1.4, 3, 2);
  const keyTarget = new Object3D();
  keyTarget.position.set(0, 0.4, 0);
  root.add(keyTarget);
  keyLight.target = keyTarget;
  root.add(keyLight);

  const practicalLight = new PointLight(new Color(colors.accent), 14, 6, 2);
  practicalLight.position.set(0, -0.65, 0.6);
  root.add(practicalLight);

  const rimLight = new DirectionalLight(new Color('#ffffff'), 1.3);
  rimLight.position.set(-1.4, 2, -2.4);
  const rimTarget = new Object3D();
  rimTarget.position.set(0, 0.5, 0);
  root.add(rimTarget);
  rimLight.target = rimTarget;
  root.add(rimLight);

  // ---- TEXT (text.hero.0, text.subhead.1, text.caption.2) ---------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjs = [];
  const roleLayout = {
    hero: { y: 0.5, fontSize: 124, color: colors.paper, align: 'center' },
    subhead: { y: -0.25, fontSize: 40, color: colors.paper, align: 'center' },
    caption: { y: -2.25, fontSize: 18, color: colors.accent, align: 'center' },
  };
  for (const item of items) {
    const layout = roleLayout[item.role] ?? { y: 0, fontSize: 32, color: colors.paper, align: 'center' };
    const fontSize = item.typography?.fontSize ?? layout.fontSize;
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: layout.color,
      align: layout.align,
      letterSpacingPx: item.role === 'caption' ? fontSize * 0.08 : 0,
    });
    textObj.position.set(0, layout.y, 0.5);
    root.add(textObj);
    textObjs.push(textObj);
  }

  // ---- CINEMATIC PRIMITIVES (primitive.particle-emerge) ------------------
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(particleGroup, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- entrance settle (weighted-settle style, non-linear) --------------
  particleGroup.scale.setScalar(0.001);
  const settleTl = gsap.timeline();
  settleTl.to(particleGroup.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 1.0,
    ease: 'power3.out',
  }).to(particleGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(settleTl);

  // ---- cleanup -------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = function cleanup() {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const fn of tickerFns) {
      gsap.ticker.remove(fn);
    }
    for (const handle of primitiveHandles) {
      handle.cleanup?.();
    }
    for (const obj of disposables) {
      obj.dispose?.();
    }
    for (const textObj of textObjs) {
      textObj.traverse?.((n) => {
        n.geometry?.dispose?.();
        if (n.material) {
          const mats = Array.isArray(n.material) ? n.material : [n.material];
          for (const m of mats) {
            m.map?.dispose?.();
            m.dispose?.();
          }
        }
      });
    }
    fieldMesh.dispose?.();
    coreMesh.dispose?.();
  };

  return root;
}

